SELECT Go.IdP, Go.Sede, Go.Cognome, Go.Nome, Go.DataN, Comuni.Comune & " / " & Comuni.Slov AS Comune, Go.[davcna koda], Go.Via, Comuni_1.Comune & "/ " & Comuni_1.Slov AS ComuneR, Comuni_1.CAP, Go.tel, Go.cel, Go.PIscr, Scuola.AnnoS, Sola.Sola, Sola.Sek, Sola.Razred, Scuola.Posk, Materia.Materia, Materia.Stejemo
FROM (((([Go] LEFT JOIN Comuni ON Go.IdCN=Comuni.IdC) LEFT JOIN Comuni AS Comuni_1 ON Go.IdCR=Comuni_1.IdC) LEFT JOIN Sola ON Go.IdP=Sola.IdP) INNER JOIN Scuola ON Go.IdP=Scuola.IdP) INNER JOIN Materia ON Scuola.IdM=Materia.IdM
GROUP BY Go.IdP, Go.Sede, Go.Cognome, Go.Nome, Go.DataN, Comuni.Comune & " / " & Comuni.Slov, Go.[davcna koda], Go.Via, Comuni_1.Comune & "/ " & Comuni_1.Slov, Comuni_1.CAP, Go.tel, Go.cel, Go.PIscr, Scuola.AnnoS, Sola.Sola, Sola.Sek, Sola.Razred, Scuola.Posk, Go.mail, Materia.Materia, Materia.Stejemo
HAVING (((Go.Sede) Like [Inserire Sede]) AND ((Scuola.AnnoS) Like [Inserire SL2]) AND ((Scuola.Posk)=0) AND ((Materia.Stejemo) Not Like "st-*"))
ORDER BY Go.Cognome, Go.Nome, Scuola.AnnoS;
